static int
ocp_word_test_and_clr_bits(struct r8152 *tp, u16 type, u16 index, u16 clear)
{
	u32 ocp_data;
	int ret;

	ret = ocp_read_word(tp, type, index, &ocp_data);
	if (ret < 0)
		goto out;

	if (ocp_data & clear) {
		ret = ocp_write_word(tp, type, index, ocp_data & ~clear);
		if (ret < 0)
			goto out;
	}
	ret = ocp_data & clear;

out:
	return ret;
}
